// ============================================================
// SOURCE ANCHORS — Makroökonomik I
// VL anchors verified against the actual Vorlesungsfolien (2026-06-08).
//
// Original VL anchors were generated by the syllabus-heading heuristic
// (populate-anchors-from-syllabus.mjs), which picked high-density pages and
// used sentence/formula fragments as section labels — and mapped several
// distinct concepts (e.g. guetermarkt/multiplikator, geldnachfrage/banken,
// islm/politikmix, phillips/islmpc/erwartungen) to the *same* pages.
//
// This pass re-anchored every VL concept to the slide that actually defines
// it, reading the official PDFs page-by-page (Poppler pdftotext -layout) and
// confirming each chosen slide title with a visual page render. locator.page
// is the PDF page index (matches the source page-index used across the
// exam-OS tooling and the Quellen panel); the slide's printed footer number
// is one lower due to Beamer title-overlay numbering.
//
// Anchor `id` strings are referenced from taskFamilies.js and formulaCards.js
// (by exact string), so ids are kept stable. The `pNN.<slug>` inside an id is
// therefore a historical tag; the student-facing truth is locator.page /
// locator.slide + section, which is what the Quellen panel renders.
//
// quoteFingerprint hashes the reviewed section label (no source text stored).
// The official Klausur task-source anchors retain their own review metadata.
// ============================================================

const REVIEWED_AT = '2026-06-08';
const REVIEWED_BY = 'codex-source-verify-makro1-vl-pass-2026-06-08';

function anchor({
  id,
  sourceId,
  sourcePath,
  publicLabel,
  page,
  section,
  fingerprint,
  confidence = 0.82,
  reviewedBy = REVIEWED_BY,
  reviewedAt = REVIEWED_AT
}) {
  return {
    id,
    sourceId,
    sourcePath,
    publicLabel,
    locator: {
      page,
      slide: page,
      section,
      task: null,
      line: null
    },
    quoteFingerprint: `sha256:${fingerprint}`,
    confidence,
    reviewedBy,
    reviewedAt
  };
}

